#include <iostream>
using namespace std;

const int V = 5;
const int INF = 1000000;

int main() {
    int graph[V][V] = {
        {0, 4, 1, 0, 0},
        {4, 0, 2, 5, 0},
        {1, 2, 0, 8, 0},
        {0, 5, 8, 0, 3},
        {0, 0, 0, 3, 0},
    };
    int key[V];
    bool inMST[V];
    int parent[V];
    for (int i = 0; i < V; i++) {
        key[i] = INF;
        inMST[i] = false;
    }
    key[0] = 0;
    parent[0] = -1;
    int total = 0;
    for (int round = 0; round < V; round++) {
        int u = -1;
        for (int i = 0; i < V; i++) {
            if (!inMST[i] && (u == -1 || key[i] < key[u])) {
                u = i;
            }
        }
        inMST[u] = true;
        total += key[u];
        for (int v = 0; v < V; v++) {
            if (graph[u][v] > 0 && !inMST[v] && graph[u][v] < key[v]) {
                key[v] = graph[u][v];
                parent[v] = u;
            }
        }
    }
    for (int v = 1; v < V; v++) {
        cout << parent[v] << " - " << v << endl;
    }
    cout << "Total weight " << total << endl;
    return 0;
}
